const input = $json.body || {};
const seq = Number(input.sequence || 0);
const fault = input.faultStable || 'none';
if (fault === 'error' || (fault === 'partial' && seq % 4 === 0)) throw new Error('Intentional demo regression');
if (fault === 'latency') await new Promise(resolve => setTimeout(resolve, 350));
const score = Math.min(100,Math.max(0,Number(input.score || 65)));
const result = {leadId: String(input.leadId || 'demo'),score,priority: score >= 70 ? 'HIGH' : 'NORMAL',engine:'stable'};
if (fault === 'invalid') result.score = 'invalid-score';
return [{json:{releaseguardVersion:'stable-v1',result}}];
